<main class="auth-card"><span class="eyebrow">Documentos</span><h1>Enviar documento</h1><form method="post" action="/admin/documents/upload" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=View::e(Security::csrfToken())?>"><label>Campeonato<input name="tournament_id" type="number" min="1" required></label><label>Título<input name="title" required></label><label>Visibilidade<select name="visibility"><option value="private">Privado</option><option value="public">Público</option></select></label><label>Arquivo PDF ou imagem<input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><button class="button primary" type="submit">Enviar</button><a class="button" href="/admin/documents">Voltar</a></form></main>
